update edu_ai_task set cancel_requested=1,update_time=sysdate()
where task_id=#{taskId} and user_id=#{userId}
  and status in ('QUEUED','RUNNING') and cancel_requested=0

update edu_ai_task set status='CANCELLED',finish_time=sysdate(),update_time=sysdate()
where task_id=#{taskId} and user_id=#{userId}
  and status='QUEUED' and cancel_requested=1
